"use client"

import { useState } from "react"
import { TodoCalendar, type TodoCalendarItem } from "@/components/rhoe/blocks/todo-calendar"

const initialItems: TodoCalendarItem[] = [
  {
    id: "review",
    title: "Review the dashboard flow",
    description: "Check motion and empty states.",
    date: new Date(2026, 9, 15),
  },
  {
    id: "publish",
    title: "Publish component documentation",
    date: new Date(2026, 9, 18),
  },
]

export function TodoCalendarExample() {
  const [date, setDate] = useState(() => new Date(2026, 9, 15))
  const [items, setItems] = useState(initialItems)

  return (
    <TodoCalendar
      items={items}
      value={date}
      onValueChange={setDate}
      onItemToggle={(selectedItem) => {
        setItems((current) => current.map((item) =>
          item.id === selectedItem.id
            ? { ...item, completed: !item.completed }
            : item
        ))
      }}
    />
  )
}

"use client"

import { useState } from "react"
import { AuthForm, type AuthFormValues } from "@/components/rhoe/blocks/auth-form"

// Replace these example endpoints with your application's authentication API.
export function SignInWithOtpRecovery() {
  const [error, setError] = useState("")

  async function post(path: string, data: object): Promise<boolean> {
    setError("")

    try {
      const response = await fetch(path, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
      })

      if (!response.ok) {
        setError("The request failed. Please try again.")
        return false
      }

      return true
    } catch {
      setError("Could not connect. Please try again.")
      return false
    }
  }

  async function handleSignIn(values: AuthFormValues) {
    const success = await post("/api/auth/sign-in", values)
    if (success) window.location.assign("/dashboard")
  }

  async function handleResetPassword(
    password: string,
    confirmPassword: string,
    email: string,
  ) {
    if (password !== confirmPassword) {
      setError("Passwords do not match.")
      return false
    }

    // The server must bind this reset request to a verified recovery session.
    const success = await post("/api/auth/reset-password", { email, password })
    if (success) window.location.assign("/sign-in")
    return success
  }

  return (
    <div>
      {error && <p role="alert">{error}</p>}

      {/* AuthForm manages button states while each async callback is pending. */}
      <AuthForm
        mode="sign-in"
        forgotPasswordVariant="otp"
        verificationCodeLength={6}
        resendCountdownSeconds={60}
        alternateAction={<a href="/sign-up">Sign up</a>}
        // Sign in → Signing in while handleSignIn is pending.
        onSubmit={handleSignIn}
        // Send OTP → Sending OTP; return false to stay on the email step.
        onForgotPassword={(email) =>
          post("/api/auth/recovery/send-code", { email })
        }
        // Verify code → Verifying code; return false for an invalid code.
        onVerifyResetCode={(code, email) =>
          post("/api/auth/recovery/verify-code", { code, email })
        }
        // Reset password → Resetting password while the request is pending.
        onResetPassword={handleResetPassword}
        onStepChange={() => setError("")}
      />
    </div>
  )
}

