import type { AuthFormValues } from "@/components/rhoe/blocks/auth-form"

async function handleSignIn(values: AuthFormValues) {
  const response = await fetch("/api/auth/sign-in", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(values),
  })

  if (!response.ok) {
    throw new Error("Unable to sign in")
  }
}

<AuthForm mode="sign-in" onSubmit={handleSignIn} />

async function handleSignUp(values: AuthFormValues) {
  const response = await fetch("/api/auth/sign-up", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(values),
  })

  return response.ok
}

async function handleVerify(code: string, email: string) {
  await fetch("/api/auth/verify", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ code, email }),
  })
}

