"use client"

import { useState } from "react"
import { RealtimeLineChart, type RealtimeLineChartProps } from "@/components/rhoe/blocks/realtime-line-chart"

const ranges = [
  { value: "30", label: "30s" },
  { value: "60", label: "1m" },
  { value: "120", label: "2m" },
]

export function LatencyChart({ metrics }: { metrics: RealtimeLineChartProps["data"] }) {
  const [range, setRange] = useState("30")

  return (
    <RealtimeLineChart
      data={metrics}
      title="API latency"
      ranges={ranges}
      range={range}
      onRangeChange={setRange}
      windowSize={Number(range) + 1}
      updateInterval={1000}
      domain={[0, 500]}
      format={{ style: "unit", unit: "millisecond" }}
    />
  )
}
